public static void generateNewMaze(){
    for(int i = 0; i < 20; i ++) {
        for(int j = 0; j < 25; j ++) {
            Main.mazeLabels[i][j].initAll();
        }
    }
    top = 0;
    row = 0;
    col = 0;
    random = new Random();
    ArrayList<MazeLabel> stack = new ArrayList<>();
    stack.add(Main.mazeLabels[0][0]);
    while(top >= 0) {
        int[] tried = {-1, -1, -1, -1};
        int triedNumber = 0;
        boolean moved = false;
        MazeLabel curLabel = stack.get(top);
        row = curLabel.row;
        col = curLabel.col;
        curLabel.setAlready();
        while(triedNumber < 4) {
            int direction = random.nextInt(4);
            if(tried[direction] == direction) {
                continue;
            }
            tried[direction] = direction;
            switch(direction) {
                case 0:
                    if(row >= 1 && !Main.mazeLabels[row - 1][col].getAlready()) {
                        curLabel.setUpAlready();
                        Main.mazeLabels[row - 1][col].setDownAlready();
                        stack.add(Main.mazeLabels[row - 1][col]);
                        top ++;
                        moved = true;
                    }
                    break;
                case 1:
                    if(row <= 18 && !Main.mazeLabels[row + 1][col].getAlready()) {
                        curLabel.setDownAlready();
                        Main.mazeLabels[row + 1][col].setUpAlready();
                        stack.add(Main.mazeLabels[row + 1][col]);
                        top ++;
                        moved = true;
                    }
                    break;
                case 2:
                    if(col >= 1 && !Main.mazeLabels[row][col - 1].getAlready()) {
                        curLabel.setLeftAlready();
                        Main.mazeLabels[row][col - 1].setRightAlready();
                        stack.add(Main.mazeLabels[row][col - 1]);
                        top ++;
                        moved = true;
                    }
                    break;
                case 3:
                    if(col <= 23 && !Main.mazeLabels[row][col + 1].getAlready()) {
                        curLabel.setRightAlready();
                        Main.mazeLabels[row][col + 1].setLeftAlready();
                        stack.add(Main.mazeLabels[row][col + 1]);
                        top ++;
                        moved = true;
                    }
                    break;
            }
            if(moved) {
                break;
            }
            triedNumber ++;
        }
        if(!moved) {
            stack.remove(top);
            top --;
        }
    }
    Main.mazeLabels[19][24].setTarget();
    Main.mazeLabels[19][24].repaint();
    Main.mazeLabels[0][0].setCurrent();
    Main.mazeLabels[0][0].repaint();
}

