        if(way.get(i) == way.get(i + 2)) {
            deadEnds.add(way.get(i + 1));
        }
    }
    for(int i = deadEnds.size() - 1; i >= 0; i --) {
        int index = way.indexOf(deadEnds.get(i));
        way.remove(index + 1);
        way.remove(index);
