import java.util.*;

public class Check {
    static final int R = 20, C = 25;

    static void buildGrid() {
        Main.mazeLabels = new MazeLabel[R][C];
        for (int i = 0; i < R; i++)
            for (int j = 0; j < C; j++) {
                Main.mazeLabels[i][j] = new MazeLabel();
                Main.mazeLabels[i][j].row = i;
                Main.mazeLabels[i][j].col = j;
            }
    }

    // walls: returns true if there is a passage between (r,c) and neighbour
    static boolean up(int r, int c)    { return Main.mazeLabels[r][c].isUpAlready(); }
    static boolean down(int r, int c)  { return Main.mazeLabels[r][c].isDownAlready(); }
    static boolean left(int r, int c)  { return Main.mazeLabels[r][c].isLeftAlready(); }
    static boolean right(int r, int c) { return Main.mazeLabels[r][c].isRightAlready(); }

    static String checkMaze(String tag) {
        StringBuilder sb = new StringBuilder();
        // 1. symmetry
        int edges = 0, asym = 0;
        for (int i = 0; i < R; i++)
            for (int j = 0; j < C; j++) {
                if (up(i, j))    { if (i == 0 || !down(i - 1, j)) asym++; }
                if (down(i, j))  { if (i == R - 1 || !up(i + 1, j)) asym++; else edges++; }
                if (left(i, j))  { if (j == 0 || !right(i, j - 1)) asym++; }
                if (right(i, j)) { if (j == C - 1 || !left(i, j + 1)) asym++; else edges++; }
            }
        // 2. connectivity via BFS from 0,0
        boolean[][] seen = new boolean[R][C];
        ArrayDeque<int[]> q = new ArrayDeque<>();
        q.add(new int[]{0, 0});
        seen[0][0] = true;
        int reached = 1;
        while (!q.isEmpty()) {
            int[] p = q.poll();
            int r = p[0], c = p[1];
            if (up(r, c) && r > 0 && !seen[r - 1][c])    { seen[r - 1][c] = true; reached++; q.add(new int[]{r - 1, c}); }
            if (down(r, c) && r < R - 1 && !seen[r + 1][c]) { seen[r + 1][c] = true; reached++; q.add(new int[]{r + 1, c}); }
            if (left(r, c) && c > 0 && !seen[r][c - 1])  { seen[r][c - 1] = true; reached++; q.add(new int[]{r, c - 1}); }
            if (right(r, c) && c < C - 1 && !seen[r][c + 1]) { seen[r][c + 1] = true; reached++; q.add(new int[]{r, c + 1}); }
        }
        sb.append(tag).append(": edges=").append(edges).append(" (perfect maze needs ")
          .append(R * C - 1).append("), asymmetricWalls=").append(asym)
          .append(", reachableCells=").append(reached).append("/").append(R * C);
        return sb.toString();
    }

    static void printAscii(boolean showWay) {
        StringBuilder sb = new StringBuilder();
        for (int j = 0; j < C; j++) sb.append("+--");
        sb.append("+\n");
        for (int i = 0; i < R; i++) {
            sb.append(left(i, 0) ? " " : "|");
            for (int j = 0; j < C; j++) {
                MazeLabel m = Main.mazeLabels[i][j];
                String cell = "  ";
                if (showWay) {
                    boolean onWay = m.upWay || m.downWay || m.leftWay || m.rightWay;
                    if (i == 0 && j == 0) cell = " S";
                    else if (i == R - 1 && j == C - 1) cell = " E";
                    else cell = onWay ? " *" : "  ";
                }
                sb.append(cell);
                sb.append(right(i, j) ? " " : "|");
            }
            sb.append("\n");
            for (int j = 0; j < C; j++) sb.append("+").append(down(i, j) ? "  " : "--");
            sb.append("+\n");
        }
        System.out.print(sb);
    }

    /** verify way-flags form a contiguous path start->exit crossing only passages */
    static String checkWay() {
        List<String> problems = new ArrayList<>();
        int marked = 0;
        for (int i = 0; i < R; i++)
            for (int j = 0; j < C; j++) {
                MazeLabel m = Main.mazeLabels[i][j];
                int deg = (m.upWay ? 1 : 0) + (m.downWay ? 1 : 0) + (m.leftWay ? 1 : 0) + (m.rightWay ? 1 : 0);
                if (deg > 0) marked++;
                // way segments must sit on carved passages and be mutual
                if (m.upWay) {
                    if (i == 0 || !up(i, j)) problems.add("upWay through wall at " + i + "," + j);
                    else if (!Main.mazeLabels[i - 1][j].downWay) problems.add("upWay not mutual at " + i + "," + j);
                }
                if (m.downWay) {
                    if (i == R - 1 || !down(i, j)) problems.add("downWay through wall at " + i + "," + j);
                    else if (!Main.mazeLabels[i + 1][j].upWay) problems.add("downWay not mutual at " + i + "," + j);
                }
                if (m.leftWay) {
                    if (j == 0 || !left(i, j)) problems.add("leftWay through wall at " + i + "," + j);
                    else if (!Main.mazeLabels[i][j - 1].rightWay) problems.add("leftWay not mutual at " + i + "," + j);
                }
                if (m.rightWay) {
                    if (j == C - 1 || !right(i, j)) problems.add("rightWay through wall at " + i + "," + j);
                    else if (!Main.mazeLabels[i][j + 1].leftWay) problems.add("rightWay not mutual at " + i + "," + j);
                }
            }
        // walk from start following way flags, forbidding immediate backtrack
        int r = 0, c = 0, prevR = -1, prevC = -1, steps = 0;
        boolean arrived = false;
        while (steps < R * C * 4) {
            if (r == R - 1 && c == C - 1) { arrived = true; break; }
            MazeLabel m = Main.mazeLabels[r][c];
            int nr = -1, nc = -1, options = 0;
            if (m.upWay    && !(r - 1 == prevR && c == prevC)) { nr = r - 1; nc = c; options++; }
            if (m.downWay  && !(r + 1 == prevR && c == prevC)) { nr = r + 1; nc = c; options++; }
            if (m.leftWay  && !(r == prevR && c - 1 == prevC)) { nr = r; nc = c - 1; options++; }
            if (m.rightWay && !(r == prevR && c + 1 == prevC)) { nr = r; nc = c + 1; options++; }
            if (options == 0) { problems.add("dead end while walking at " + r + "," + c); break; }
            if (options > 1) { problems.add("branch (" + options + " ways) at " + r + "," + c); }
            prevR = r; prevC = c; r = nr; c = nc; steps++;
        }
        return "way: cellsMarked=" + marked + " walkSteps=" + steps + " reachedExit=" + arrived
                + " problems=" + (problems.isEmpty() ? "none" : problems.toString());
    }

    public static void main(String[] a) throws Exception {
        int trials = a.length > 0 ? Integer.parseInt(a[0]) : 200;
        boolean dump = a.length > 1;
        String worst = null;
        for (int t = 0; t < trials; t++) {
            buildGrid();
            MazeTools.generateNewMaze();
            String s1 = checkMaze("DFS  ");
            GetWay.getWay();
            String w1 = checkWay();
