                if (!s.contains("asymmetricWalls=0") || !s.contains("reachableCells=500/500")
                        || !s.contains("edges=499")) { worst = s; }
            }
            for (String w : new String[]{w1, w2}) {
                if (!w.contains("reachedExit=true") || !w.contains("problems=none")) { worst = w; }
            }
        }
        System.out.println("trials=" + trials + " firstBadResult=" + (worst == null ? "NONE - all clean" : worst));
        if (dump) {
            buildGrid();
            MazeTools.generateNewMaze();
            GetWay.getWay();
            System.out.println("--- DFS-generated maze with solution path ---");
            printAscii(true);
            buildGrid();
            PrimGenerate.primGenerate();
            GetWay.getWay();
            System.out.println("--- Prim-generated maze with solution path ---");
            printAscii(true);
        }
    }
}

