import java.awt.*;
import java.awt.event.ActionListener;
import java.awt.image.BufferedImage;
import java.lang.reflect.Field;
import java.lang.reflect.Method;
import javax.swing.*;

public class Check2 {

    static Object unsafe() throws Exception {
        Class<?> c = Class.forName("sun.misc.Unsafe");
        Field f = c.getDeclaredField("theUnsafe");
        f.setAccessible(true);
        return f.get(null);
    }

    public static void main(String[] args) throws Exception {
        // ---------- paintComponent ----------
        MazeLabel lab = new MazeLabel();
        lab.setSize(30, 30);
        lab.setUpAlready();          // no green line on top
        lab.setRightAlready();       // no green line on right
        lab.downWay = true;          // blue stub downward
        lab.rightWay = true;         // blue stub rightward
        lab.setTarget();             // yellow disc
        BufferedImage img = new BufferedImage(30, 30, BufferedImage.TYPE_INT_RGB);
        Graphics2D g = img.createGraphics();
        Method pc = MazeLabel.class.getDeclaredMethod("paintComponent", Graphics.class);
        pc.setAccessible(true);
        pc.invoke(lab, g);
        g.dispose();
        System.out.println("paintComponent ran OK");
        System.out.println("  top    (15,1)  green? " + hex(img, 15, 1)  + "  (expect NOT green: upAlready)");
        System.out.println("  bottom (10,29) green? " + hex(img, 10, 29) + "  (expect green: wall present)");
        System.out.println("  left   (1,10)  green? " + hex(img, 1, 10)  + "  (expect green: wall present)");
        System.out.println("  right  (29,20) green? " + hex(img, 29, 20) + "  (expect NOT green: rightAlready)");
        System.out.println("  centre (15,15) = " + hex(img, 15, 15) + "  (expect blue: way stubs drawn over disc)");
        System.out.println("  disc   (8,8)   = " + hex(img, 8, 8)   + "  (expect yellow: isTarget)");
        System.out.println("  down stub (15,25) = " + hex(img, 15, 25) + "  (expect blue)");
        System.out.println("  right stub (25,15) = " + hex(img, 25, 15) + "  (expect blue)");

        MazeLabel lab2 = new MazeLabel();
        lab2.setSize(30, 30);
        lab2.setCurrent();
        BufferedImage img2 = new BufferedImage(30, 30, BufferedImage.TYPE_INT_RGB);
        Graphics2D g2 = img2.createGraphics();
        pc.invoke(lab2, g2);
        g2.dispose();
        System.out.println("  current disc (15,15) = " + hex(img2, 15, 15) + "  (expect red: isCurrent)");
        lab2.initAll();
        BufferedImage img3 = new BufferedImage(30, 30, BufferedImage.TYPE_INT_RGB);
        Graphics2D g3 = img3.createGraphics();
        pc.invoke(lab2, g3);
        g3.dispose();
        System.out.println("  after initAll (15,15) = " + hex(img3, 15, 15) + "  (expect black/blank), walls all drawn? "
                + (isGreen(img3, 15, 1) && isGreen(img3, 15, 29) && isGreen(img3, 1, 15) && isGreen(img3, 29, 15)));

        // ---------- initTable / initComp (no JFrame constructor) ----------
        Object u = unsafe();
        Method alloc = u.getClass().getMethod("allocateInstance", Class.class);
        Main main = (Main) alloc.invoke(u, Main.class);

        JPanel panel = new JPanel();
        panel.setLayout(null);
        setField(Main.class, null, "mainPanel", panel);
        Main.mazeLabels = new MazeLabel[20][25];
        setField(Main.class, main, "startBtn", new JButton("深度优先算法开始"));
        setField(Main.class, main, "primStart", new JButton("随机Prim算法开始"));
        setField(Main.class, main, "refresh", new JButton("刷新"));
        setField(Main.class, main, "findWayBtn", new JButton("寻找一条路"));

        Method initTable = Main.class.getDeclaredMethod("initTable");
        initTable.setAccessible(true);
        initTable.invoke(main);
        System.out.println("initTable ran OK: panel children=" + panel.getComponentCount()
                + " (expect 500)  cell[0][0].bounds=" + Main.mazeLabels[0][0].getBounds()
                + " cell[19][24].bounds=" + Main.mazeLabels[19][24].getBounds()
                + " row/col[7][13]=" + Main.mazeLabels[7][13].row + "/" + Main.mazeLabels[7][13].col);

        Method initComp = Main.class.getDeclaredMethod("initComp");
        initComp.setAccessible(true);
        initComp.invoke(main);
        System.out.println("initComp ran OK: panel children=" + panel.getComponentCount() + " (expect 505)");
        for (Component c : panel.getComponents()) {
            if (c instanceof JButton) System.out.println("  button " + ((JButton) c).getText() + " " + c.getBounds());
        }
        for (Component c : panel.getComponents()) {
            if (c instanceof JLabel && !(c instanceof MazeLabel)) {
                JLabel jl = (JLabel) c;
                System.out.println("  label bounds=" + jl.getBounds() + " hAlign=" + jl.getHorizontalAlignment()
                        + " vAlign=" + jl.getVerticalAlignment());
                System.out.println("  label text=" + jl.getText());
            }
        }
        // fire the listeners exactly as a click would
        for (Component c : panel.getComponents()) {
            if (c instanceof JButton) {
                JButton b = (JButton) c;
                ActionListener[] ls = b.getActionListeners();
                System.out.print("  clicking '" + b.getText() + "' listeners=" + ls.length);
                for (ActionListener l : ls) l.actionPerformed(null);
                int visited = 0;
                for (int i = 0; i < 20; i++) for (int j = 0; j < 25; j++) if (Main.mazeLabels[i][j].getAlready()) visited++;
                System.out.println(" -> cellsCarved=" + visited);
            }
        }
    }

    static void setField(Class<?> c, Object target, String name, Object v) throws Exception {
        Field f = c.getDeclaredField(name);
        f.setAccessible(true);
        f.set(target, v);
    }

    static boolean isGreen(BufferedImage i, int x, int y) { return (i.getRGB(x, y) & 0xFFFFFF) == 0x00FF00; }

    static String hex(BufferedImage i, int x, int y) {
        int rgb = i.getRGB(x, y) & 0xFFFFFF;
        String name = rgb == 0x00FF00 ? "GREEN" : rgb == 0x0000FF ? "BLUE" : rgb == 0xFFFF00 ? "YELLOW"
                : rgb == 0xFF0000 ? "RED" : rgb == 0x000000 ? "blank" : "other";
        return String.format("#%06X(%s)", rgb, name);
    }
}

